def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents alive, take water cheaply
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids to infer pressure
    prev_bids = []
    prev_by_id = {}
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                bid_val = float(bid)
            except Exception:
                continue
            prev_bids.append(bid_val)
            prev_by_id[opp_id] = bid_val

    # Determine pressure level
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Estimate how many units of water likely matter for our requirement
    # (We only need enough to avoid running out; bidding should scale with supply.)
    # Use a conservative target: if supply is near requirement, we must win.
    supply_ratio = supply / float(WATER_REQ)

    # Base bid: aim around a fraction of salary to avoid overspending
    # Increase if our hp is low or if yesterday showed very high bids.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Pressure triggers
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.8
    medium_pressure = (highest_prev_bid >= DAILY_SALARY * 0.5) or (second_prev_bid >= DAILY_SALARY * 0.35)

    # If we are in danger, bid more aggressively
    if hp <= 2.0 or no_water_days >= 2:
        urgency_factor = 0.95
    elif hp <= 4.0:
        urgency_factor = 0.75
    else:
        urgency_factor = 0.55

    # If supply is tight, we must secure water
    if supply_ratio < 1.05:
        tight_factor = 1.15
    elif supply_ratio < 1.25:
        tight_factor = 1.0
    else:
        tight_factor = 0.9

    # Competitive adjustment: try to be slightly above the likely second-best bidder
    # to avoid paying the absolute highest.
    if prev_bids:
        target_competitive = second_prev_bid + 2.0
    else:
        target_competitive = DAILY_SALARY * 0.5

    # Decide bid
    if high_pressure:
        bid = max(target_competitive, DAILY_SALARY * 0.65) * urgency_factor * tight_factor
    elif medium_pressure:
        bid = max(target_competitive, DAILY_SALARY * 0.5) * (urgency_factor * 0.95) * tight_factor
    else:
        bid = max(target_competitive, DAILY_SALARY * 0.45) * (urgency_factor * 0.9) * tight_factor

    # Cap to avoid bankrupting: keep some budget buffer for later days
    # Use a soft cap depending on remaining days (episode_days not provided here, so use day).
    # Earlier days allow slightly more spending.
    if day <= 3:
        buffer_frac = 0.25
    elif day <= 7:
        buffer_frac = 0.35
    else:
        buffer_frac = 0.45

    max_affordable = max(0.0, budget * (1.0 - buffer_frac))
    bid = min(bid, max_affordable, budget)

    # Ensure minimal bid if we must act
    if bid <= 0.0:
        bid = min(budget, DAILY_SALARY * 0.3)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
