    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_pressure = 0
    weak_pressure = 0
    desperate_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                desperate_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 120:
                    strong_pressure += 1
                elif bid <= 70:
                    weak_pressure += 1

    if not alive:
        return float(min(budget, 20.0))

    low_supply = supply <= 17
    high_supply = supply >= 22
    critical_me = hp <= 2 or no_water_days >= 2
    risky_me = hp <= 4 or no_water_days >= 1

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 80.0
        avg_prev = 80.0

    if critical_me:
        target = max(145.0, highest_prev + 6.0)
        if high_supply:
            target = max(110.0, avg_prev + 3.0)
        return float(min(budget, target))

    if low_supply and strong_pressure >= 2 and hp >= 6:
        return float(min(budget, 28.0))

    if high_supply:
        if weak_pressure >= len(prev_bids) - strong_pressure:
            target = max(58.0, avg_prev + 2.0)
        else:
            target = max(72.0, min(115.0, avg_prev * 0.72))
        if desperate_opponents >= 2:
            target += 8.0
        return float(min(budget, target))

    target = 0.0
    if highest_prev >= 150:
        if hp >= 6:
            target = 35.0
        else:
            target = 118.0
    elif highest_prev >= 110:
        target = highest_prev + 2.0 if risky_me else 62.0
    else:
        target = max(60.0, avg_prev + 3.0)

    if desperate_opponents >= 2:
        target += 10.0
    if day >= 8 and hp >= 6 and not risky_me:
        target *= 0.9

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
